// Tablet expressiveness index — record JAH-GPCS-DRAWINGTABLET-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"pressure_levels": 8192, "active_area_in2": 40};
var value = (m.pressure_levels/1000*m.active_area_in2);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-DRAWINGTABLET-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-DRAWINGTABLET-000001|' + value.toFixed(2) + ' expressiveness index');

